package dev.eugheist.tc4modern;

import net.minecraft.core.BlockPos;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

/** Dedicated production goal checks with real chest capabilities and dropped items. */
@EventBusSubscriber(modid=TC4Modern.MODID)
final class GolemConfigAudit {
 static void check(boolean good,String text){if(!good)throw new IllegalStateException("TC4_GOLEM_CONFIG FAIL "+text);System.out.println("TC4_GOLEM_CONFIG PASS "+text);}
 @SubscribeEvent static void started(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!Boolean.getBoolean("tc4modern.golemConfigAudit"))return;var server=e.getServer();try{
 check(WarpConfig.SPEC.isLoaded()&&GolemConfig.delay()==7&&GolemConfig.ignoreDelay()==12345,"actual TOML loads seven ticks and 12345 milliseconds");
 var l=server.overworld();var at=new BlockPos(0,180,0);l.setBlock(at,Blocks.CHEST.defaultBlockState(),3);var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(at);chest.clearContent();
 var g=new StrawGolem(Golemancy.ENTITY.get(),l);g.material(GolemMaterial.THAUMIUM,true);g.home=at.above();g.homeFace=net.minecraft.core.Direction.UP;g.moveTo(.5,181,.5,0,0);g.getEntityData().set(StrawGolem.CORE,(byte)0);g.carried(new ItemStack(Items.COBBLESTONE,3));var inv=l.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,at,g.homeFace);var goal=new GolemInventoryGoal(g);
 g.tickCount=5;goal.deposit(inv,at);check(!g.carried().isEmpty()&&chest.isEmpty(),"actual home deposit skips former hardcoded tick five");g.tickCount=7;goal.deposit(inv,at);check(g.carried().isEmpty()&&chest.getItem(0).getCount()==3,"actual home deposit transfers three items on configured tick seven");
 check(GolemConfig.chestInteract()&&GolemChests.OPEN.get(l)!=null&&GolemChests.OPEN.get(l).get(at)==5&&GolemChests.opened==1&&net.minecraft.world.level.block.entity.ChestBlockEntity.getOpenCount(l,at)==0,"default golem_chest_interact opens the home chest on a real deposit without counting a player");
 for(int t=0;t<4;t++)GolemChests.tick(new net.neoforged.neoforge.event.tick.LevelTickEvent.Post(()->true,l));check(GolemChests.OPEN.get(l).containsKey(at)&&GolemChests.closed==0,"chest stays open through the original five-tick countChest");GolemChests.tick(new net.neoforged.neoforge.event.tick.LevelTickEvent.Post(()->true,l));check(!GolemChests.OPEN.get(l).containsKey(at)&&GolemChests.closed==1,"chest closes when the task would reset");
 GolemConfig.CHEST_INTERACT.set(false);g.carried(new ItemStack(Items.COBBLESTONE,1));goal.deposit(inv,at);check(g.carried().isEmpty()&&!GolemChests.OPEN.get(l).containsKey(at)&&GolemChests.opened==1,"golem_chest_interact false transfers silently without opening");GolemConfig.CHEST_INTERACT.set(true);chest.clearContent();chest.setItem(0,new ItemStack(Items.COBBLESTONE,3));
 var item=new net.minecraft.world.entity.item.ItemEntity(l,.5,181,.5,new ItemStack(Items.OAK_LOG));item.setNoPickUpDelay();l.addFreshEntity(item);var gather=new StrawGolem.Gather(g);g.getEntityData().set(StrawGolem.CORE,(byte)2);g.tickCount=5;gather.tick();check(g.carried().isEmpty(),"actual gather search skips former tick five");g.tickCount=7;gather.tick();check(g.carried().is(Items.OAK_LOG)&&!item.isAlive(),"actual gather search picks up item on configured tick seven");item.discard();g.carried(ItemStack.EMPTY);
 var sorting=new GolemSortingGoal(g);g.getEntityData().set(StrawGolem.CORE,(byte)10);g.tickCount=7;long before=System.currentTimeMillis();sorting.tick();check(sorting.timeout.size()==1,"actual sorter records failed item without destination");long until=sorting.timeout.values().iterator().next();check(until>=before+12345&&until<=System.currentTimeMillis()+12345,"actual sorter deadline uses configured wall-clock milliseconds");check(sorting.onTimeout(new ItemStack(Items.COBBLESTONE)),"actual sorter ignores matching failed item");sorting.timeout.replaceAll((s,t)->System.currentTimeMillis()-1);check(!sorting.onTimeout(new ItemStack(Items.COBBLESTONE)),"actual sorter clears expired wall-clock timeout");
 var use=new GolemUseGoal(g);g.getEntityData().set(StrawGolem.CORE,(byte)8);g.filters.setItem(0,new ItemStack(Items.COBBLESTONE));before=System.currentTimeMillis();use.tick();check(use.timeout.size()==1,"actual use core records filtered item with no marker");until=use.timeout.values().iterator().next();check(until>=before+12345&&until<=System.currentTimeMillis()+12345,"actual use-core deadline uses configured wall-clock milliseconds");use.timeout.replaceAll((s,t)->System.currentTimeMillis()-1);check(!use.onTimeout(new ItemStack(Items.COBBLESTONE)),"actual use core clears expired timeout");
 var empty=new StrawGolem(Golemancy.ENTITY.get(),l);empty.material(GolemMaterial.THAUMIUM,true);empty.home=at.above();empty.homeFace=net.minecraft.core.Direction.UP;empty.moveTo(.5,181,.5,0,0);empty.getEntityData().set(StrawGolem.CORE,(byte)1);var job=new GolemInventoryGoal(empty);chest.clearContent();chest.setItem(0,new ItemStack(Items.COBBLESTONE,10));chest.setItem(1,new ItemStack(Items.DIRT,4));
 var dest=at.east(2);l.setBlock(dest,Blocks.CHEST.defaultBlockState(),3);var target=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(dest);target.clearContent();empty.tickCount=7;long emptyBefore=System.currentTimeMillis();job.tick();check(empty.carried().isEmpty()&&chest.getItem(0).getCount()==10&&chest.getItem(1).getCount()==4,"actual empty core leaves home items without any marked destination");check(job.timeout.size()==2&&job.timeout.values().stream().allMatch(t->t>=emptyBefore+12345&&t<=System.currentTimeMillis()+12345),"actual empty core ignores both failed home items for configured milliseconds");
 var mark=new net.minecraft.nbt.CompoundTag();mark.putLong("pos",dest.asLong());mark.putByte("side",(byte)net.minecraft.core.Direction.UP.get3DDataValue());empty.markers.add(mark);empty.tickCount=14;job.tick();check(empty.carried().isEmpty(),"actual empty core keeps ignoring items until wall-clock deadline");job.timeout.replaceAll((s,t)->System.currentTimeMillis()-1);empty.tickCount=21;job.tick();check(empty.carried().is(Items.COBBLESTONE)&&empty.carried().getCount()==10&&chest.getItem(0).isEmpty(),"actual empty core takes first item once destination exists and timeout expired");check(GolemChests.OPEN.get(l).containsKey(at),"empty-core home take opens the home chest");
 for(int i=0;i<27;i++)target.setItem(i,new ItemStack(Items.STONE,64));empty.tickCount=28;int returnedBefore=GolemInventoryGoal.returned;job.tick();check(job.returning&&job.onTimeout(new ItemStack(Items.COBBLESTONE)),"actual full destination marks carried load ignored and returning");check(empty.carried().isEmpty()&&chest.getItem(0).is(Items.COBBLESTONE)&&chest.getItem(0).getCount()==10&&GolemInventoryGoal.returned==returnedBefore+1,"actual AIHomeReplace puts undeliverable load back into home chest");
 target.clearContent();empty.tickCount=35;job.tick();check(empty.carried().is(Items.DIRT)&&chest.getItem(0).getCount()==10,"actual empty core skips still-ignored cobblestone and takes deliverable dirt");empty.moveTo(dest.getX()+.5,dest.getY()+1,dest.getZ()+.5,0,0);empty.tickCount=42;job.tick();check(empty.carried().isEmpty()&&target.getItem(0).is(Items.DIRT)&&target.getItem(0).getCount()==4,"actual empty core delivers deliverable load to marked chest");check(GolemChests.OPEN.get(l).containsKey(dest),"empty-core delivery opens the marked chest");l.removeBlock(dest,false);
 GolemConfig.DELAY.set(1);g.carried(new ItemStack(Items.DIRT));g.tickCount=5;goal.deposit(inv,at);check(g.carried().isEmpty(),"live minimum one-tick setting takes effect");
 System.out.println("TC4_GOLEM_CONFIG ALL PASS TOML, real transfers, gather searches, wall-clock failed-item timeouts and empty-core home replacement");
 }finally{server.halt(false);}}
}
